&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Aptos&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:220,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Ownership.&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;You spot the problem and walk it to your boss&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;→&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;We fall in love with problems.&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Own&amp;nbsp;them.&amp;nbsp;Solve&amp;nbsp;them. Ship&amp;nbsp;solutions.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
